"""Sort and dedupe citations of the form 'T. Kestrel Stat. ann. sec S'."""

import re
import sys


def normalize(citation: str) -> str:
    """Collapse internal whitespace runs to single spaces, strip ends."""
    return " ".join(citation.split())


def section_key(section: str):
    """Numeric-aware dotted comparison key: 14.9 < 14.10 < 14.302.1."""
    return tuple(int(part) for part in section.split("."))


def citation_key(citation: str):
    """Key for sorting: (title as int, section as dotted numeric tuple)."""
    match = re.fullmatch(
        r"(\d+)\. Kestrel Stat\. ann\. sec (\d+(?:\.\d+)*)", citation
    )
    if not match:
        raise ValueError(f"Malformed citation: {citation!r}")
    title, section = match.groups()
    return (int(title), section_key(section))


def sort_citations(citations):
    """Normalize whitespace, dedupe, sort by title then section."""
    unique = {normalize(c) for c in citations}
    return sorted(unique, key=citation_key)


def main():
    lines = sys.stdin.read().splitlines()
    for citation in sort_citations(lines):
        print(citation)


if __name__ == "__main__":
    main()

